import { NgModule } from '@angular/core';
import { BrowserModule } from '@angular/platform-browser';
import { FormsModule } from '@angular/forms';
import { HttpClientModule } from '@angular/common/http';

import { AppComponent } from './app.component';
import { AppRoutingModule } from './app-routing.module';
import { LeaveApplicationComponent } from './components/leave-application/leave-application.component';
import { LeaveTrackerComponent } from './components/leave-tracker/leave-tracker.component';
import { EmployeeLeaveStatusComponent } from './components/employee-leave-status/employee-leave-status.component';

@NgModule({
  declarations: [
    AppComponent,
    LeaveApplicationComponent,
    LeaveTrackerComponent,
    EmployeeLeaveStatusComponent
  ],
  imports: [
    BrowserModule,
    FormsModule,
    HttpClientModule,
    AppRoutingModule
  ],
  providers: [],
  bootstrap: [AppComponent]
})
export class AppModule { }
